export const formatNumber = (value, { digits = 1 } = {}) => {
    return (value || 0).toLocaleString("en-US", {
        maximumFractionDigits: digits,
    });
};
export const formatTruncatedNumber = (number, { digits = 1 } = {}) => {
    const [THOUSAND, MILLION, BILLION, TRILLION, QUADRILLION] = [
        1e3, 1e6, 1e9, 1e12, 1e15,
    ];
    switch (true) {
        case number >= QUADRILLION:
            return `${formatNumber(number / QUADRILLION, { digits: 1 })}q`;
        case number >= TRILLION:
            return `${formatNumber(number / TRILLION, { digits: 1 })}t`;
        case number >= BILLION:
            return `${formatNumber(number / BILLION, { digits: 1 })}b`;
        case number >= MILLION:
            return `${formatNumber(number / MILLION, { digits: 1 })}m`;
        case number >= THOUSAND:
            return `${formatNumber(number / THOUSAND, { digits: 1 })}k`;
        default:
            return formatNumber(number, { digits });
    }
};
